from sympy import sec, sqrt, sin, tan, csc, symbols, Rational as Q, N
t=symbols('t')
e=sqrt((sec(t)+1)/(sec(t)-1))+sqrt((sec(t)-1)/(sec(t)+1))
opts={'A':2*csc(t),'B':2*tan(t)*sec(t),'C':2*sin(t),'D':2*tan(t)}
ok=[]
for k,v in opts.items():
    if all(abs(N((e-v).subs(t,a)))<1e-9 for a in [Q(3,10),Q(7,10),Q(11,10)]): ok.append(k)
assert ok==['A']
